SELECT CASE WHEN status_bits >= 11 THEN 'LARGE' ELSE 'SMALL' END AS status_bits_tier, CASE WHEN humidity >= 75 THEN 'LARGE' ELSE 'SMALL' END AS humidity_tier, ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) AS pressure_per_dv_02, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS span_minutes, MAX(temp_c) AS max_temp_c FROM device_readings GROUP BY ROLLUP (CASE WHEN status_bits >= 11 THEN 'LARGE' ELSE 'SMALL' END, CASE WHEN humidity >= 75 THEN 'LARGE' ELSE 'SMALL' END) HAVING ROUND(SUM(pressure) / NULLIF(COUNT(CASE WHEN device_code = 'DV-02' THEN 1 END), 0), 2) > 0 ORDER BY humidity_tier DESC;
